__hydrateVak("vmbo","na1",{"A":{"sv":[{"v":"Wat is dichtheid?","o":["De massa per volume","Het volume","De massa","De temperatuur"],"c":0,"d":1,"u":"Massa gedeeld door volume.","uo":["Klopt: massa gedeeld door volume.","Volume is maar een deel.","Massa is maar een deel.","Temperatuur is iets anders."],"uh":"De massa per volume: Massa gedeeld door volume."},{"v":"Een blok van 200 g heeft een volume van 100 cm³. Wat is de dichtheid?","o":["200 g/cm³","2 g/cm³","100 g/cm³","0,5 g/cm³"],"c":1,"d":3,"u":"200 / 100 = 2 g/cm³.","uo":["Dat is de massa.","Klopt: 200 / 100 = 2 g/cm³.","Dat is het volume.","Deel massa door volume."],"uh":"2 g/cm³: 200 / 100 = 2 g/cm³."},{"v":"Hoe heet de overgang van vast naar vloeibaar?","o":["Stollen","Verdampen","Smelten","Condenseren"],"c":2,"d":1,"u":"Vast wordt vloeibaar.","uo":["Stollen is andersom.","Dat is vloeibaar naar gas.","Klopt: vast wordt vloeibaar.","Dat is gas naar vloeibaar."],"uh":"Smelten: Vast wordt vloeibaar."},{"v":"Water verdampt. Welke faseovergang is dit?","o":["Vast naar vloeibaar","Gas naar vloeibaar","Vast naar gas","Vloeibaar naar gas"],"c":3,"d":2,"u":"Vloeibaar wordt gas.","uo":["Dat is smelten.","Dat is condenseren.","Dat is iets anders.","Klopt: vloeibaar wordt gas."],"uh":"Vloeibaar wordt gas."},{"v":"Bij welke temperatuur smelt een stof?","o":["Bij het smeltpunt","Altijd bij nul graden","Bij kamertemperatuur","Bij het kookpunt"],"c":0,"d":2,"u":"Bij het smeltpunt.","uo":["Klopt: bij het smeltpunt.","Niet elke stof bij nul.","Niet per se.","Dat is bij koken."],"uh":"Bij het smeltpunt."},{"v":"Wat gebeurt er met de temperatuur tijdens het smelten?","o":["Die stijgt snel","Die blijft even gelijk","Die daalt","Die verdwijnt"],"c":1,"d":2,"u":"Tijdens de faseovergang blijft de temperatuur gelijk.","uo":["Nee, even niet.","Klopt: tijdens de faseovergang blijft de temperatuur gelijk.","Nee, het juiste antwoord is «Die blijft even gelijk».","Temperatuur verdwijnt niet."],"uh":"Die blijft even gelijk: Tijdens de faseovergang blijft de temperatuur gelijk."},{"v":"Wat is massa?","o":["De ruimte die iets inneemt","De dichtheid","De hoeveelheid stof","De temperatuur"],"c":2,"d":1,"u":"De hoeveelheid stof in gram of kg.","uo":["Dat is volume.","Iets anders.","Klopt: de hoeveelheid stof in gram of kg.","Iets anders."],"uh":"De hoeveelheid stof in gram of kg."},{"v":"Wat is volume?","o":["De hoeveelheid stof","De massa per volume","De warmte","De ruimte die iets inneemt"],"c":3,"d":1,"u":"De ingenomen ruimte.","uo":["Dat is massa.","Dat is dichtheid.","Iets anders.","Klopt: de ingenomen ruimte."],"uh":"De ruimte die iets inneemt: De ingenomen ruimte."},{"v":"IJs wordt water. Hoe heet dat?","o":["Smelten","Condenseren","Stollen","Verdampen"],"c":0,"d":2,"u":"Vast wordt vloeibaar.","uo":["Klopt: vast wordt vloeibaar.","Dat is gas naar vloeibaar.","Dat is vloeibaar naar vast.","Dat is vloeibaar naar gas."],"uh":"Smelten: Vast wordt vloeibaar."},{"v":"Waterdamp wordt weer water. Hoe heet dat?","o":["Smelten","Condenseren","Verdampen","Stollen"],"c":1,"d":2,"u":"Gas wordt vloeibaar.","uo":["Dat is vast naar vloeibaar.","Klopt: gas wordt vloeibaar.","Dat is vloeibaar naar gas.","Dat is vloeibaar naar vast."],"uh":"Condenseren: Gas wordt vloeibaar."},{"v":"Een stof met een grote dichtheid is...","o":["licht voor zijn grootte","altijd een vaste stof","zwaar voor zijn grootte","altijd warm"],"c":2,"d":2,"u":"Veel massa in weinig volume.","uo":["Nee, juist zwaar.","Niet per se.","Klopt: veel massa in weinig volume.","Niet per se."],"uh":"zwaar voor zijn grootte: Veel massa in weinig volume."},{"v":"Welke fase heeft een vaste vorm én een vast volume?","o":["Gas","Vloeistof","Damp","Vaste stof"],"c":3,"d":1,"u":"Een vaste stof.","uo":["Gas vult de ruimte.","Vloeistof neemt de vorm van de bak aan.","Damp is een gas.","Klopt: een vaste stof."],"uh":"Vaste stof: Een vaste stof."}],"begrippen":[{"t":"Dichtheid","d":"de massa per volume van een stof"},{"t":"Massa","d":"de hoeveelheid stof, in kilogram of gram"},{"t":"Volume","d":"de ruimte die een stof inneemt"},{"t":"Faseovergang","d":"de overgang van de ene fase naar de andere"},{"t":"Smelten","d":"de overgang van vast naar vloeibaar"},{"t":"Stollen","d":"de overgang van vloeibaar naar vast"},{"t":"Verdampen","d":"de overgang van vloeibaar naar gas"},{"t":"Condenseren","d":"de overgang van gas naar vloeibaar"},{"t":"Smeltpunt","d":"de temperatuur waarbij een stof smelt"},{"t":"Kookpunt","d":"de temperatuur waarbij een stof kookt"},{"t":"Vaste stof","d":"een stof met een vaste vorm en een vast volume"},{"t":"Vloeistof","d":"een stof die vloeit en de vorm van de bak aanneemt"},{"t":"Gas","d":"een stof die de hele beschikbare ruimte vult"},{"t":"Temperatuur-tijdgrafiek","d":"een grafiek van de temperatuur tegen de tijd bij verwarmen"}],"sam":"<div class=\"sam-intro\">De <strong>dichtheid</strong> is de massa per volume van een stof. Bij een <strong>faseovergang</strong> gaat een stof van vast naar vloeibaar of van vloeibaar naar gas. Een <strong>temperatuur-tijdgrafiek</strong> laat zien hoe de temperatuur tijdens verwarmen verandert.</div><div class=\"sam-head\">1. Dichtheid</div><p>De <strong>dichtheid</strong> vertelt hoe zwaar een stof is voor zijn grootte: de <strong>massa</strong> per <strong>volume</strong>. IJzer heeft een grote dichtheid, piepschuim een kleine. Je berekent de dichtheid door de massa te delen door het volume.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Dichtheid</div><div class=\"sam-formula-eq\">ρ = m / V</div><div class=\"sam-formula-note\">ρ de dichtheid (g/cm³ of kg/m³), m de massa, V het volume.</div></div><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Een blok heeft een massa van 200 g en een volume van 100 cm³. Bereken de dichtheid.</div><ol class=\"sam-worked-steps\"><li>Gebruik ρ = m / V.</li><li>ρ = 200 / 100.</li></ol><div class=\"sam-worked-ans\">✅ De dichtheid is 2 g/cm³.</div></div><div class=\"sam-head\">2. Faseovergangen</div><p>Een stof kan <strong>vast</strong>, <strong>vloeibaar</strong> of <strong>gas</strong> zijn. De overgangen hebben eigen namen: <strong>smelten</strong> (vast → vloeibaar) en <strong>stollen</strong> (vloeibaar → vast), en <strong>verdampen</strong> (vloeibaar → gas) en <strong>condenseren</strong> (gas → vloeibaar). Het <strong>smeltpunt</strong> en het <strong>kookpunt</strong> zijn de temperaturen waarbij dat gebeurt.</p><div class=\"sam-head\">3. Temperatuur-tijdgrafiek</div><p>In een <strong>temperatuur-tijdgrafiek</strong> zet je de temperatuur uit tegen de tijd bij verwarmen. Tijdens een faseovergang blijft de temperatuur even gelijk (een vlak stuk in de grafiek), omdat alle warmte in de overgang gaat zitten.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Dichtheid</div><div class=\"sam-definitie-body\">de massa per volume van een stof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Massa</div><div class=\"sam-definitie-body\">de hoeveelheid stof, in kilogram of gram.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Volume</div><div class=\"sam-definitie-body\">de ruimte die een stof inneemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Faseovergang</div><div class=\"sam-definitie-body\">de overgang van de ene fase naar de andere.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Smelten</div><div class=\"sam-definitie-body\">de overgang van vast naar vloeibaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stollen</div><div class=\"sam-definitie-body\">de overgang van vloeibaar naar vast.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verdampen</div><div class=\"sam-definitie-body\">de overgang van vloeibaar naar gas.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Condenseren</div><div class=\"sam-definitie-body\">de overgang van gas naar vloeibaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Smeltpunt</div><div class=\"sam-definitie-body\">de temperatuur waarbij een stof smelt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kookpunt</div><div class=\"sam-definitie-body\">de temperatuur waarbij een stof kookt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vaste stof</div><div class=\"sam-definitie-body\">een stof met een vaste vorm en een vast volume.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vloeistof</div><div class=\"sam-definitie-body\">een stof die vloeit en de vorm van de bak aanneemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gas</div><div class=\"sam-definitie-body\">een stof die de hele beschikbare ruimte vult.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Temperatuur-tijdgrafiek</div><div class=\"sam-definitie-body\">een grafiek van de temperatuur tegen de tijd bij verwarmen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Dichtheid»</b> is massa per volume, terwijl <b>«Massa»</b> hoeveelheid stof is. <b>«Massa»</b> is hoeveelheid stof, terwijl <b>«Volume»</b> ingenomen ruimte is. <b>«Faseovergang»</b> is wisseling van fase, terwijl <b>«Smelten»</b> vast wordt vloeibaar is. <b>«Smelten»</b> is vast wordt vloeibaar, terwijl <b>«Stollen»</b> vloeibaar wordt vast is.</div>"},"B":{"sv":[{"v":"Wat meet je in ampère?","o":["De stroomsterkte","De spanning","De weerstand","Het vermogen"],"c":0,"d":1,"u":"Stroomsterkte in ampère.","uo":["Klopt: stroomsterkte in ampère.","Spanning is in volt.","Weerstand is in ohm.","Vermogen is in watt."],"uh":"De stroomsterkte: Stroomsterkte in ampère."},{"v":"Wat meet je in volt?","o":["De stroom","De spanning","De weerstand","Het vermogen"],"c":1,"d":1,"u":"Spanning in volt.","uo":["Stroom is in ampère.","Klopt: spanning in volt.","Weerstand is in ohm.","Vermogen in watt."],"uh":"De spanning: Spanning in volt."},{"v":"Wat meet je in ohm?","o":["De stroom","De spanning","De weerstand","De energie"],"c":2,"d":1,"u":"Weerstand in ohm.","uo":["Stroom in ampère.","Spanning in volt.","Klopt: weerstand in ohm.","Energie in joule."],"uh":"De weerstand: Weerstand in ohm."},{"v":"Door een lamp loopt 0,5 A bij 6 V. Wat is de weerstand?","o":["3 ohm","6 ohm","0,5 ohm","12 ohm"],"c":3,"d":3,"u":"R = U / I = 6 / 0,5 = 12 ohm.","uo":["Deel U door I.","Dat is de spanning.","Dat is de stroom.","Klopt: R = U / I = 6 / 0,5 = 12 ohm."],"uh":"12 ohm: R = U / I = 6 / 0,5 = 12 ohm."},{"v":"In een serieschakeling heeft de stroom...","o":["maar één weg","meerdere wegen","geen weg","een dubbele weg"],"c":0,"d":2,"u":"Één weg door de keten.","uo":["Klopt: één weg door de keten.","Dat is parallel.","Er is wel stroom.","Onjuist, het juiste antwoord is «maar één weg»."],"uh":"maar één weg: Één weg door de keten."},{"v":"Eén lampje gaat stuk en de rest gaat ook uit. Wat voor schakeling?","o":["Parallel","Serie","Kortsluiting","Geen schakeling"],"c":1,"d":3,"u":"In serie valt alles uit.","uo":["Bij parallel blijft de rest aan.","Klopt: in serie valt alles uit.","Iets anders.","Er is wel een schakeling."],"uh":"Serie: In serie valt alles uit."},{"v":"Wat laat een geleider door?","o":["Alleen warmte","Geen stroom","Stroom","Alleen licht"],"c":2,"d":1,"u":"Een geleider laat stroom door.","uo":["Niet alleen warmte.","Dat is een isolator.","Klopt: een geleider laat stroom door.","Niet alleen licht."],"uh":"Stroom: Een geleider laat stroom door."},{"v":"Wat doet een isolator?","o":["Stroom goed doorlaten","Stroom versterken","Stroom opwekken","Stroom tegenhouden"],"c":3,"d":2,"u":"Een isolator laat geen stroom door.","uo":["Dat is een geleider.","Nee, het juiste antwoord is «Stroom tegenhouden».","Nee, het juiste antwoord is «Stroom tegenhouden».","Klopt: een isolator laat geen stroom door."],"uh":"Stroom tegenhouden: Een isolator laat geen stroom door."},{"v":"Wat is vermogen?","o":["De energie per seconde","De totale energie","De spanning","De weerstand"],"c":0,"d":2,"u":"De energie per seconde, in watt.","uo":["Klopt: de energie per seconde, in watt.","Dat is energie.","Spanning is iets anders.","Weerstand is iets anders."],"uh":"De energie per seconde, in watt."},{"v":"Een apparaat van 100 W staat 2 uur aan. Hoeveel energie?","o":["50 Wh","200 Wh","100 Wh","2 Wh"],"c":1,"d":3,"u":"E = P × t = 100 × 2 = 200 Wh.","uo":["Onjuist, het juiste antwoord is «200 Wh».","Klopt: E = P × t = 100 × 2 = 200 Wh.","Dat is het vermogen.","Dat is de tijd."],"uh":"200 Wh: E = P × t = 100 × 2 = 200 Wh."},{"v":"Wat is een zekering?","o":["Een lamp","Een batterij","Een beveiliging tegen te veel stroom","Een schakelaar"],"c":2,"d":1,"u":"Onderbreekt de stroom bij te veel stroom.","uo":["Een lamp geeft licht.","Een batterij levert stroom.","Klopt: onderbreekt de stroom bij te veel stroom.","Iets anders."],"uh":"Een beveiliging tegen te veel stroom: Onderbreekt de stroom bij te veel stroom."},{"v":"Wat gebeurt er bij kortsluiting?","o":["De stroom stopt netjes","Er loopt geen stroom","De weerstand stijgt","Er loopt heel veel stroom"],"c":3,"d":3,"u":"Bijna geen weerstand, dus heel veel stroom.","uo":["Nee, het juiste antwoord is «Er loopt heel veel stroom».","Er loopt juist veel.","Nee, juist heel laag.","Klopt: bijna geen weerstand, dus heel veel stroom."],"uh":"Er loopt heel veel stroom: Bijna geen weerstand, dus heel veel stroom."}],"begrippen":[{"t":"Stroomsterkte","d":"de hoeveelheid lading die per seconde stroomt, in ampère"},{"t":"Spanning","d":"de duw die de stroom veroorzaakt, in volt"},{"t":"Weerstand","d":"de mate waarin een component de stroom tegenwerkt, in ohm"},{"t":"Wet van Ohm","d":"het verband tussen spanning, stroom en weerstand (U = I × R)"},{"t":"Serieschakeling","d":"een schakeling waarin de stroom maar één weg heeft"},{"t":"Parallelschakeling","d":"een schakeling met meerdere takken naast elkaar"},{"t":"Vermogen","d":"de energie die per seconde wordt omgezet, in watt"},{"t":"Elektrische energie","d":"de energie die een apparaat gebruikt in een bepaalde tijd"},{"t":"Geleider","d":"een materiaal dat de stroom goed doorlaat"},{"t":"Isolator","d":"een materiaal dat de stroom niet doorlaat"},{"t":"Kortsluiting","d":"een verbinding met heel weinig weerstand"},{"t":"Zekering","d":"een beveiliging die de stroom onderbreekt bij te veel stroom"}],"sam":"<div class=\"sam-intro\">In een stroomkring horen <strong>spanning</strong>, <strong>stroomsterkte</strong> en <strong>weerstand</strong> bij elkaar, verbonden door de <strong>wet van Ohm</strong>. In een <strong>serieschakeling</strong> heeft de stroom één weg, in een <strong>parallelschakeling</strong> meerdere.</div><div class=\"sam-head\">1. Stroom, spanning en weerstand</div><p>De <strong>stroomsterkte</strong> (in ampère) is de hoeveelheid lading die per seconde stroomt. De <strong>spanning</strong> (in volt) is de duw die de stroom veroorzaakt. De <strong>weerstand</strong> (in ohm) werkt de stroom tegen. Een <strong>geleider</strong> laat stroom goed door, een <strong>isolator</strong> niet.</p><div class=\"sam-head\">2. De wet van Ohm</div><p>Spanning, stroom en weerstand hangen samen: hoe hoger de weerstand bij dezelfde spanning, hoe kleiner de stroom.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Wet van Ohm</div><div class=\"sam-formula-eq\">U = I × R</div><div class=\"sam-formula-note\">U de spanning (V), I de stroomsterkte (A), R de weerstand (Ω).</div></div><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Door een lampje loopt 0,5 A bij een spanning van 6 V. Bereken de weerstand.</div><ol class=\"sam-worked-steps\"><li>Herschrijf U = I × R naar R = U / I.</li><li>R = 6 / 0,5.</li></ol><div class=\"sam-worked-ans\">✅ De weerstand is 12 Ω.</div></div><div class=\"sam-head\">3. Serie en parallel</div><p>In een <strong>serieschakeling</strong> heeft de stroom maar één weg: gaat één lampje stuk, dan doet de rest het ook niet. In een <strong>parallelschakeling</strong> zijn er takken naast elkaar. Een <strong>kortsluiting</strong> is een verbinding met bijna geen weerstand; een <strong>zekering</strong> onderbreekt dan de stroom.</p><div class=\"sam-head\">4. Vermogen en energie</div><p>Het <strong>vermogen</strong> (in watt) is de energie die per seconde wordt omgezet. De <strong>elektrische energie</strong> die een apparaat gebruikt, hangt af van het vermogen én de tijd dat het aanstaat.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Vermogen en energie</div><div class=\"sam-formula-eq\">P = U × I   en   E = P × t</div><div class=\"sam-formula-note\">P het vermogen (W), E de energie (J of Wh), t de tijd.</div></div><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Een apparaat van 100 W staat 2 uur aan. Bereken de gebruikte energie.</div><ol class=\"sam-worked-steps\"><li>Gebruik E = P × t.</li><li>E = 100 W × 2 h.</li></ol><div class=\"sam-worked-ans\">✅ De energie is 200 Wh (0,2 kWh).</div></div><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stroomsterkte</div><div class=\"sam-definitie-body\">de hoeveelheid lading die per seconde stroomt, in ampère.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Spanning</div><div class=\"sam-definitie-body\">de duw die de stroom veroorzaakt, in volt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Weerstand</div><div class=\"sam-definitie-body\">de mate waarin een component de stroom tegenwerkt, in ohm.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wet van Ohm</div><div class=\"sam-definitie-body\">het verband tussen spanning, stroom en weerstand (U = I × R).</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Serieschakeling</div><div class=\"sam-definitie-body\">een schakeling waarin de stroom maar één weg heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Parallelschakeling</div><div class=\"sam-definitie-body\">een schakeling met meerdere takken naast elkaar.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vermogen</div><div class=\"sam-definitie-body\">de energie die per seconde wordt omgezet, in watt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Elektrische energie</div><div class=\"sam-definitie-body\">de energie die een apparaat gebruikt in een bepaalde tijd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geleider</div><div class=\"sam-definitie-body\">een materiaal dat de stroom goed doorlaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Isolator</div><div class=\"sam-definitie-body\">een materiaal dat de stroom niet doorlaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kortsluiting</div><div class=\"sam-definitie-body\">een verbinding met heel weinig weerstand.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zekering</div><div class=\"sam-definitie-body\">een beveiliging die de stroom onderbreekt bij te veel stroom.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Stroomsterkte»</b> is lading per seconde, terwijl <b>«Spanning»</b> de elektrische duw is. <b>«Weerstand»</b> is werkt de stroom tegen, terwijl <b>«Stroomsterkte»</b> lading per seconde is. <b>«Wet van Ohm»</b> is U is I maal R, terwijl <b>«Vermogen»</b> energie per seconde is. <b>«Serieschakeling»</b> is één stroomweg, terwijl <b>«Parallelschakeling»</b> takken naast elkaar is.</div>"},"C":{"sv":[{"v":"Metaal geeft warmte door zonder zelf te bewegen. Hoe heet dat?","o":["Warmtegeleiding","Warmtestroming","Warmtestraling","Isolatie"],"c":0,"d":2,"u":"Geleiding, de stof beweegt niet.","uo":["Klopt: geleiding, de stof beweegt niet.","Bij stroming beweegt de stof.","Straling gaat door de ruimte.","Isolatie houdt warmte tegen."],"uh":"Warmtegeleiding: Geleiding, de stof beweegt niet."},{"v":"De zon warmt de aarde op. Hoe gaat die warmte?","o":["Geleiding","Straling","Stroming","Isolatie"],"c":1,"d":2,"u":"Straling, zonder tussenstof.","uo":["Geleiding heeft een stof nodig.","Klopt: straling, zonder tussenstof.","Stroming heeft een stof nodig.","Isolatie houdt warmte tegen."],"uh":"Straling, zonder tussenstof."},{"v":"Wat is isolatie?","o":["Warmte opwekken","Warmte doorgeven","Warmte tegenhouden","Warmte meten"],"c":2,"d":1,"u":"Warmtetransport tegenhouden.","uo":["Nee, het juiste antwoord is «Warmte tegenhouden».","Dat is geleiding.","Klopt: warmtetransport tegenhouden.","Nee, het juiste antwoord is «Warmte tegenhouden»."],"uh":"Warmte tegenhouden: Warmtetransport tegenhouden."},{"v":"Wat is nodig voor verbranding?","o":["Alleen warmte","Alleen licht","Water","Brandstof en zuurstof"],"c":3,"d":2,"u":"Brandstof reageert met zuurstof.","uo":["Niet genoeg.","Nee, het juiste antwoord is «Brandstof en zuurstof».","Nee, juist niet.","Klopt: brandstof reageert met zuurstof."],"uh":"Brandstof reageert met zuurstof."},{"v":"Warme lucht stijgt op, koude zakt. Hoe heet dit warmtetransport?","o":["Stroming","Geleiding","Straling","Verbranding"],"c":0,"d":2,"u":"Stroming met bewegende lucht.","uo":["Klopt: stroming met bewegende lucht.","Daar beweegt de stof niet.","Straling gaat door de ruimte.","Iets anders."],"uh":"Stroming met bewegende lucht."},{"v":"Wat is rendement?","o":["Alle energie","Het nuttig gebruikte deel","De verloren energie","De brandstof"],"c":1,"d":2,"u":"Het deel dat nuttig wordt gebruikt.","uo":["Nee, niet alles.","Klopt: het deel dat nuttig wordt gebruikt.","Juist het tegenovergestelde.","Brandstof is iets anders."],"uh":"Het nuttig gebruikte deel: Het deel dat nuttig wordt gebruikt."},{"v":"Wat is een goede warmte-isolator?","o":["Water","Metaal","Piepschuim","Koper"],"c":2,"d":2,"u":"Piepschuim houdt warmte tegen.","uo":["Water geleidt redelijk.","Metaal geleidt juist goed.","Klopt: piepschuim houdt warmte tegen.","Koper geleidt heel goed."],"uh":"Piepschuim houdt warmte tegen."},{"v":"Waarom voelt metaal koud aan?","o":["Het maakt zelf kou","Het is altijd koud","Het straalt kou uit","Het geleidt de warmte snel weg"],"c":3,"d":3,"u":"Metaal geleidt je lichaamswarmte snel weg.","uo":["Kou bestaat niet als stof.","Niet altijd.","Kou straal je niet uit.","Klopt: metaal geleidt je lichaamswarmte snel weg."],"uh":"Het geleidt de warmte snel weg: Metaal geleidt je lichaamswarmte snel weg."},{"v":"Wat komt vrij bij een verbranding?","o":["Warmte","Kou","Alleen water","Niets"],"c":0,"d":1,"u":"Er komt warmte vrij.","uo":["Klopt: er komt warmte vrij.","Nee, het juiste antwoord is «Warmte».","Niet alleen water.","Er gebeurt wel iets."],"uh":"Warmte: Er komt warmte vrij."},{"v":"Wat is soortelijke warmte?","o":["De temperatuur","De warmte per kg per graad","De massa","Het volume"],"c":1,"d":2,"u":"Warmte om 1 kg 1 graad op te warmen.","uo":["Nee, het juiste antwoord is «De warmte per kg per graad».","Klopt: warmte om 1 kg 1 graad op te warmen.","Nee, het juiste antwoord is «De warmte per kg per graad».","Nee, het juiste antwoord is «De warmte per kg per graad»."],"uh":"De warmte per kg per graad: Warmte om 1 kg 1 graad op te warmen."},{"v":"Je verwarmt 2 kg water (c = 4180) 10 °C op. Q = c·m·ΔT is...","o":["20.900 J","4.180 J","83.600 J","2.000 J"],"c":2,"d":3,"u":"4180 × 2 × 10 = 83.600 J.","uo":["Onjuist, het juiste antwoord is «83.600 J».","Dat is c, het juiste antwoord is «83.600 J».","Klopt: 4180 × 2 × 10 = 83.600 J.","Dat is de massa in gram."],"uh":"83.600 J: 4180 × 2 × 10 = 83.600 J."},{"v":"Waarom draag je in de kou een dikke jas?","o":["Om warmte te maken","Om te stralen","Om te verbranden","Om warmte binnen te houden"],"c":3,"d":2,"u":"De jas isoleert en houdt je warmte binnen.","uo":["Een jas maakt geen warmte.","Nee, het juiste antwoord is «Om warmte binnen te houden».","Nee, het juiste antwoord is «Om warmte binnen te houden».","Klopt: de jas isoleert en houdt je warmte binnen."],"uh":"Om warmte binnen te houden: De jas isoleert en houdt je warmte binnen."}],"begrippen":[{"t":"Warmtegeleiding","d":"warmtetransport door een stof zonder dat de stof zelf beweegt"},{"t":"Warmtestroming","d":"warmtetransport doordat een vloeistof of gas beweegt"},{"t":"Warmtestraling","d":"warmtetransport via straling, zonder tussenstof"},{"t":"Isolatie","d":"het tegenhouden van warmtetransport"},{"t":"Verbranding","d":"een reactie met zuurstof waarbij warmte vrijkomt"},{"t":"Brandstof","d":"een stof die je verbrandt om energie te krijgen"},{"t":"Zuurstof","d":"het gas dat nodig is voor verbranding"},{"t":"Soortelijke warmte","d":"de warmte om één kilogram van een stof één graad op te warmen"},{"t":"Warmtegeleider","d":"een materiaal dat warmte goed doorlaat"},{"t":"Warmte-isolator","d":"een materiaal dat warmte slecht doorlaat"},{"t":"Rendement","d":"het deel van de energie dat nuttig wordt gebruikt"},{"t":"Convectie","d":"een andere naam voor warmtestroming in vloeistof of gas"}],"sam":"<div class=\"sam-intro\">Warmte gaat over door <strong>geleiding</strong>, <strong>stroming</strong> of <strong>straling</strong>. Met <strong>isolatie</strong> houd je warmte tegen. Bij <strong>verbranding</strong> reageert een <strong>brandstof</strong> met <strong>zuurstof</strong> en komt er warmte vrij.</div><div class=\"sam-head\">1. Warmtetransport</div><p>Warmte kan op drie manieren van warm naar koud gaan. Bij <strong>warmtegeleiding</strong> geeft een stof de warmte door zonder zelf te bewegen (metaal). Bij <strong>warmtestroming</strong> beweegt een vloeistof of gas mee (verwarming in huis). Bij <strong>warmtestraling</strong> gaat de warmte door straling, zonder tussenstof (de zon). Met <strong>isolatie</strong> hou je warmtetransport tegen.</p><div class=\"sam-head\">2. Verbranding</div><p>Bij een <strong>verbranding</strong> reageert een <strong>brandstof</strong> met <strong>zuurstof</strong> en komt warmte vrij. Het <strong>rendement</strong> zegt welk deel van de energie nuttig wordt gebruikt; de rest gaat als warmte verloren.</p><div class=\"sam-head\">3. Soortelijke warmte</div><p>Hoeveel warmte een stof nodig heeft om op te warmen, hangt af van de <strong>soortelijke warmte</strong> (c), de massa en de temperatuurstijging.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Warmte</div><div class=\"sam-formula-eq\">Q = c × m × ΔT</div><div class=\"sam-formula-note\">Q de warmte (J), c de soortelijke warmte, m de massa (kg), ΔT de temperatuurstijging (°C).</div></div><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Je verwarmt 2 kg water (c = 4180) van 20 °C naar 30 °C. Bereken de warmte.</div><ol class=\"sam-worked-steps\"><li>Bepaal ΔT = 30 − 20 = 10 °C.</li><li>Q = c × m × ΔT = 4180 × 2 × 10.</li></ol><div class=\"sam-worked-ans\">✅ Er is 83.600 J warmte nodig.</div></div><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Warmtegeleiding</div><div class=\"sam-definitie-body\">warmtetransport door een stof zonder dat de stof zelf beweegt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Warmtestroming</div><div class=\"sam-definitie-body\">warmtetransport doordat een vloeistof of gas beweegt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Warmtestraling</div><div class=\"sam-definitie-body\">warmtetransport via straling, zonder tussenstof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Isolatie</div><div class=\"sam-definitie-body\">het tegenhouden van warmtetransport.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verbranding</div><div class=\"sam-definitie-body\">een reactie met zuurstof waarbij warmte vrijkomt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Brandstof</div><div class=\"sam-definitie-body\">een stof die je verbrandt om energie te krijgen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zuurstof</div><div class=\"sam-definitie-body\">het gas dat nodig is voor verbranding.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Soortelijke warmte</div><div class=\"sam-definitie-body\">de warmte om één kilogram van een stof één graad op te warmen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Warmtegeleider</div><div class=\"sam-definitie-body\">een materiaal dat warmte goed doorlaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Warmte-isolator</div><div class=\"sam-definitie-body\">een materiaal dat warmte slecht doorlaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rendement</div><div class=\"sam-definitie-body\">het deel van de energie dat nuttig wordt gebruikt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Convectie</div><div class=\"sam-definitie-body\">een andere naam voor warmtestroming in vloeistof of gas.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Warmtegeleiding»</b> is warmte door een stof, terwijl <b>«Warmtestroming»</b> warmte met bewegende stof is. <b>«Warmtestraling»</b> is warmte via straling, terwijl <b>«Warmtegeleiding»</b> warmte door een stof is. <b>«Isolatie»</b> is warmte tegenhouden, terwijl <b>«Warmtegeleiding»</b> warmte door een stof is. <b>«Verbranding»</b> is reactie met zuurstof, terwijl <b>«Isolatie»</b> warmte tegenhouden is.</div>"},"D":{"sv":[{"v":"Wat gebeurt er bij spiegeling?","o":["Licht kaatst terug","Licht buigt af","Licht verdwijnt","Licht wordt warmer"],"c":0,"d":2,"u":"Licht kaatst terug.","uo":["Klopt: licht kaatst terug.","Dat is breking.","Licht verdwijnt niet.","Nee, het juiste antwoord is «Licht kaatst terug»."],"uh":"Licht kaatst terug."},{"v":"Licht gaat van lucht in water en verandert van richting. Hoe heet dat?","o":["Spiegeling","Lichtbreking","Terugkaatsing","Straling"],"c":1,"d":2,"u":"Lichtbreking bij overgang naar een andere stof.","uo":["Dat is terugkaatsen.","Klopt: lichtbreking bij overgang naar een andere stof.","Idem, het juiste antwoord is «Lichtbreking».","Iets anders."],"uh":"Lichtbreking bij overgang naar een andere stof."},{"v":"Wat doet een bolle lens?","o":["Licht tegenhouden","Licht spreiden","Licht bundelen","Licht kleuren"],"c":2,"d":1,"u":"Een bolle lens brengt licht samen.","uo":["Nee, het juiste antwoord is «Licht bundelen».","Dat doet een holle lens.","Klopt: een bolle lens brengt licht samen.","Nee, het juiste antwoord is «Licht bundelen»."],"uh":"Licht bundelen: Een bolle lens brengt licht samen."},{"v":"Wat doet een holle lens?","o":["Licht bundelen","Licht opwarmen","Licht tegenhouden","Licht spreiden"],"c":3,"d":2,"u":"Een holle lens spreidt het licht.","uo":["Dat doet een bolle lens.","Nee, het juiste antwoord is «Licht spreiden».","Nee, het juiste antwoord is «Licht spreiden».","Klopt: een holle lens spreidt het licht."],"uh":"Licht spreiden: Een holle lens spreidt het licht."},{"v":"Wat is het brandpunt van een bolle lens?","o":["Waar het licht samenkomt","Waar de lens breekt","De rand van de lens","Het midden van de lens"],"c":0,"d":2,"u":"Waar evenwijdige stralen samenkomen.","uo":["Klopt: waar evenwijdige stralen samenkomen.","Nee, het juiste antwoord is «Waar het licht samenkomt».","Nee, het juiste antwoord is «Waar het licht samenkomt».","Nee, het juiste antwoord is «Waar het licht samenkomt»."],"uh":"Waar het licht samenkomt: Waar evenwijdige stralen samenkomen."},{"v":"Welk beeld kun je op een scherm opvangen?","o":["Een virtueel beeld","Een reëel beeld","Een spiegelbeeld","Geen enkel beeld"],"c":1,"d":2,"u":"Een reëel beeld vang je op een scherm.","uo":["Dat kun je niet opvangen.","Klopt: een reëel beeld vang je op een scherm.","Idem, het juiste antwoord is «Een reëel beeld».","Er is wel een beeld."],"uh":"Een reëel beeld vang je op een scherm."},{"v":"Wat voor beeld zie je in een spiegel?","o":["Geen beeld","Een reëel beeld","Een virtueel beeld","Een warm beeld"],"c":2,"d":2,"u":"Een virtueel beeld, niet op te vangen.","uo":["Er is wel een beeld.","Dat vang je juist op.","Klopt: een virtueel beeld, niet op te vangen.","Nee, het juiste antwoord is «Een virtueel beeld»."],"uh":"Een virtueel beeld, niet op te vangen."},{"v":"Wat is een lichtstraal?","o":["Een warm punt","Een gekleurd vlak","Een spiegel","Een rechte lijn die de richting toont"],"c":3,"d":1,"u":"Een rechte lijn die de richting van licht toont.","uo":["Nee, het juiste antwoord is «Een rechte lijn die de richting toont».","Nee, het juiste antwoord is «Een rechte lijn die de richting toont».","Nee, het juiste antwoord is «Een rechte lijn die de richting toont».","Klopt: een rechte lijn die de richting van licht toont."],"uh":"Een rechte lijn die de richting van licht toont."},{"v":"Bij spiegeling is de invalshoek...","o":["gelijk aan de terugkaatshoek","groter dan de terugkaatshoek","veel kleiner","niet te meten"],"c":0,"d":3,"u":"De invalshoek is gelijk aan de terugkaatshoek.","uo":["Klopt: de invalshoek is gelijk aan de terugkaatshoek.","Nee, het juiste antwoord is «gelijk aan de terugkaatshoek».","Nee, het juiste antwoord is «gelijk aan de terugkaatshoek».","Je kunt hem meten."],"uh":"gelijk aan de terugkaatshoek: De invalshoek is gelijk aan de terugkaatshoek."},{"v":"Waardoor lijkt een rietje in een glas water geknikt?","o":["Door spiegeling","Door lichtbreking","Door warmte","Door de kleur"],"c":1,"d":3,"u":"Het licht breekt bij de overgang water-lucht.","uo":["Nee, het juiste antwoord is «Door lichtbreking».","Klopt: het licht breekt bij de overgang water-lucht.","Nee, het juiste antwoord is «Door lichtbreking».","Nee, het juiste antwoord is «Door lichtbreking»."],"uh":"Door lichtbreking: Het licht breekt bij de overgang water-lucht."},{"v":"Wat is een lens?","o":["Een lamp","Een spiegel","Doorzichtig voorwerp dat licht buigt","Een gekleurd glas"],"c":2,"d":1,"u":"Een lens bundelt of spreidt licht.","uo":["Een lamp geeft licht.","Een spiegel kaatst terug.","Klopt: een lens bundelt of spreidt licht.","Nee, het juiste antwoord is «Doorzichtig voorwerp dat licht buigt»."],"uh":"Doorzichtig voorwerp dat licht buigt: Een lens bundelt of spreidt licht."},{"v":"Een loep vergroot. Wat voor lens zit erin?","o":["Een holle lens","Een spiegel","Geen lens","Een bolle lens"],"c":3,"d":3,"u":"Een bolle lens.","uo":["Die spreidt juist.","Nee, het juiste antwoord is «Een bolle lens».","Er zit wel een lens in.","Klopt: een bolle lens."],"uh":"Een bolle lens."}],"begrippen":[{"t":"Lichtstraal","d":"een rechte lijn die de richting van het licht aangeeft"},{"t":"Spiegeling","d":"het terugkaatsen van licht door een spiegel"},{"t":"Lichtbreking","d":"het veranderen van richting van licht bij overgang naar een andere stof"},{"t":"Lens","d":"een doorzichtig voorwerp dat licht bundelt of spreidt"},{"t":"Bolle lens","d":"een lens die lichtstralen bij elkaar brengt"},{"t":"Holle lens","d":"een lens die lichtstralen uit elkaar laat gaan"},{"t":"Brandpunt","d":"het punt waar een bolle lens evenwijdige stralen samenbrengt"},{"t":"Beeld","d":"de afbeelding die door een lens of spiegel ontstaat"},{"t":"Reëel beeld","d":"een beeld dat je op een scherm kunt opvangen"},{"t":"Virtueel beeld","d":"een beeld dat je niet kunt opvangen, zoals in een spiegel"},{"t":"Invalshoek","d":"de hoek waaronder licht op een oppervlak valt"},{"t":"Terugkaatsing","d":"het weerkaatsen van licht tegen een oppervlak"}],"sam":"<div class=\"sam-intro\">Licht gaat rechtdoor tot het wordt <strong>teruggekaatst</strong> of <strong>gebroken</strong>. Een <strong>bolle lens</strong> bundelt licht in het <strong>brandpunt</strong>, een <strong>holle lens</strong> spreidt het.</div><div class=\"sam-head\">1. Terugkaatsing en breking</div><p>Een <strong>lichtstraal</strong> gaat rechtdoor tot hij een oppervlak raakt. Bij <strong>spiegeling</strong> kaatst het licht terug; de <strong>invalshoek</strong> is dan gelijk aan de terugkaatshoek. Gaat licht van de ene stof naar de andere (lucht naar water), dan verandert het van richting: <strong>lichtbreking</strong>.</p><div class=\"sam-head\">2. Lenzen en beeld</div><p>Een <strong>bolle lens</strong> brengt lichtstralen bij elkaar in het <strong>brandpunt</strong>; een <strong>holle lens</strong> laat ze juist uit elkaar gaan. Zo ontstaat een <strong>beeld</strong>. Een <strong>reëel beeld</strong> kun je op een scherm opvangen; een <strong>virtueel beeld</strong> niet, zoals je spiegelbeeld.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lichtstraal</div><div class=\"sam-definitie-body\">een rechte lijn die de richting van het licht aangeeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Spiegeling</div><div class=\"sam-definitie-body\">het terugkaatsen van licht door een spiegel.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lichtbreking</div><div class=\"sam-definitie-body\">het veranderen van richting van licht bij overgang naar een andere stof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lens</div><div class=\"sam-definitie-body\">een doorzichtig voorwerp dat licht bundelt of spreidt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bolle lens</div><div class=\"sam-definitie-body\">een lens die lichtstralen bij elkaar brengt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Holle lens</div><div class=\"sam-definitie-body\">een lens die lichtstralen uit elkaar laat gaan.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Brandpunt</div><div class=\"sam-definitie-body\">het punt waar een bolle lens evenwijdige stralen samenbrengt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Beeld</div><div class=\"sam-definitie-body\">de afbeelding die door een lens of spiegel ontstaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reëel beeld</div><div class=\"sam-definitie-body\">een beeld dat je op een scherm kunt opvangen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Virtueel beeld</div><div class=\"sam-definitie-body\">een beeld dat je niet kunt opvangen, zoals in een spiegel.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Invalshoek</div><div class=\"sam-definitie-body\">de hoek waaronder licht op een oppervlak valt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Terugkaatsing</div><div class=\"sam-definitie-body\">het weerkaatsen van licht tegen een oppervlak.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Lichtstraal»</b> is richting van licht, terwijl <b>«Lichtbreking»</b> licht verandert richting is. <b>«Spiegeling»</b> is licht kaatst terug, terwijl <b>«Lichtbreking»</b> licht verandert richting is. <b>«Lens»</b> is bundelt of spreidt licht, terwijl <b>«Bolle lens»</b> brengt licht samen is. <b>«Bolle lens»</b> is brengt licht samen, terwijl <b>«Holle lens»</b> spreidt licht is.</div>"},"E":{"sv":[{"v":"Waaruit bestaat geluid?","o":["Uit trillingen","Uit licht","Uit warmte","Uit stroom"],"c":0,"d":1,"u":"Trillingen die zich voortplanten.","uo":["Klopt: trillingen die zich voortplanten.","Nee, het juiste antwoord is «Uit trillingen».","Nee, het juiste antwoord is «Uit trillingen».","Nee, het juiste antwoord is «Uit trillingen»."],"uh":"Uit trillingen: Trillingen die zich voortplanten."},{"v":"Wat is de frequentie?","o":["De hardheid","Het aantal trillingen per seconde","De duur van één trilling","De snelheid"],"c":1,"d":2,"u":"Trillingen per seconde, in hertz.","uo":["Dat is geluidssterkte.","Klopt: trillingen per seconde, in hertz.","Dat is de trillingstijd.","Iets anders."],"uh":"Het aantal trillingen per seconde: Trillingen per seconde, in hertz."},{"v":"Wat bepaalt de toonhoogte?","o":["De kleur","De amplitude","De frequentie","De temperatuur"],"c":2,"d":2,"u":"Een hoge frequentie geeft een hoge toon.","uo":["Nee, het juiste antwoord is «De frequentie».","Dat bepaalt de sterkte.","Klopt: een hoge frequentie geeft een hoge toon.","Nee, het juiste antwoord is «De frequentie»."],"uh":"De frequentie: Een hoge frequentie geeft een hoge toon."},{"v":"Wat bepaalt hoe hard een geluid klinkt?","o":["De frequentie","De trillingstijd","De temperatuur","De amplitude"],"c":3,"d":2,"u":"De amplitude bepaalt de geluidssterkte.","uo":["Dat bepaalt de toonhoogte.","Iets anders.","Nee, het juiste antwoord is «De amplitude».","Klopt: de amplitude bepaalt de geluidssterkte."],"uh":"De amplitude bepaalt de geluidssterkte."},{"v":"Een trilling duurt 0,01 s. Wat is de frequentie? (f = 1/T)","o":["100 Hz","10 Hz","1 Hz","0,01 Hz"],"c":0,"d":3,"u":"1 / 0,01 = 100 Hz.","uo":["Klopt: 1 / 0,01 = 100 Hz.","Onjuist, het juiste antwoord is «100 Hz».","Onjuist, het juiste antwoord is «100 Hz».","Dat is de tijd."],"uh":"100 Hz: 1 / 0,01 = 100 Hz."},{"v":"Waardoor kan geluid zich NIET voortplanten?","o":["Door lucht","Door het luchtledige","Door water","Door een muur"],"c":1,"d":3,"u":"In vacuüm is er niets om te trillen.","uo":["Lucht kan trillen.","Klopt: in vacuüm is er niets om te trillen.","Water kan trillen.","Een muur trilt ook."],"uh":"Door het luchtledige: In vacuüm is er niets om te trillen."},{"v":"Wat is een echo?","o":["Een hoge toon","Heel hard geluid","Teruggekaatst geluid","Een lichtstraal"],"c":2,"d":1,"u":"Geluid dat terugkaatst.","uo":["Nee, het juiste antwoord is «Teruggekaatst geluid».","Niet per se hard.","Klopt: geluid dat terugkaatst.","Geluid is geen licht."],"uh":"Teruggekaatst geluid: Geluid dat terugkaatst."},{"v":"Waarmee meet je met geluid een afstand?","o":["Met een frequentie","Met de amplitude","Met een lens","Met echopeiling"],"c":3,"d":2,"u":"Echopeiling gebruikt de tijd van de echo.","uo":["Nee, het juiste antwoord is «Met echopeiling».","Nee, het juiste antwoord is «Met echopeiling».","Een lens is voor licht.","Klopt: echopeiling gebruikt de tijd van de echo."],"uh":"Met echopeiling: Echopeiling gebruikt de tijd van de echo."},{"v":"Wat is de trillingstijd?","o":["De tijd van één trilling","Het aantal trillingen","De hardheid","De snelheid"],"c":0,"d":2,"u":"De duur van één trilling.","uo":["Klopt: de duur van één trilling.","Dat is de frequentie.","Nee, het juiste antwoord is «De tijd van één trilling».","Nee, het juiste antwoord is «De tijd van één trilling»."],"uh":"De tijd van één trilling: De duur van één trilling."},{"v":"Wat is de amplitude?","o":["Het aantal trillingen","De grootte van de uitwijking","De toonhoogte","De snelheid"],"c":1,"d":2,"u":"De grootte van de uitwijking.","uo":["Nee, het juiste antwoord is «De grootte van de uitwijking».","Klopt: de grootte van de uitwijking.","Nee, het juiste antwoord is «De grootte van de uitwijking».","Nee, het juiste antwoord is «De grootte van de uitwijking»."],"uh":"De grootte van de uitwijking."},{"v":"Wat is de geluidssnelheid in lucht ongeveer?","o":["3.400 m/s","34 m/s","340 m/s","1 m/s"],"c":2,"d":2,"u":"Ongeveer 340 m/s.","uo":["Te hoog, het juiste antwoord is «340 m/s».","Te laag, het juiste antwoord is «340 m/s».","Klopt: ongeveer 340 m/s.","Veel te laag."],"uh":"340 m/s: Ongeveer 340 m/s."},{"v":"Een lage bromtoon heeft een...","o":["hoge frequentie","grote amplitude","korte trillingstijd","lage frequentie"],"c":3,"d":3,"u":"Een lage toon heeft een lage frequentie.","uo":["Nee, dat is een hoge toon.","Dat gaat over hardheid.","Nee, het juiste antwoord is «lage frequentie».","Klopt: een lage toon heeft een lage frequentie."],"uh":"lage frequentie: Een lage toon heeft een lage frequentie."}],"begrippen":[{"t":"Geluid","d":"trillingen die zich door een stof voortplanten"},{"t":"Trilling","d":"een heen-en-weergaande beweging"},{"t":"Frequentie","d":"het aantal trillingen per seconde, in hertz"},{"t":"Trillingstijd","d":"de tijd van één volledige trilling"},{"t":"Amplitude","d":"de grootte van de uitwijking van een trilling"},{"t":"Toonhoogte","d":"hoe hoog of laag een toon klinkt; hangt af van de frequentie"},{"t":"Geluidssterkte","d":"hoe hard een geluid klinkt; hangt af van de amplitude"},{"t":"Geluidssnelheid","d":"de snelheid waarmee geluid zich voortplant"},{"t":"Echo","d":"geluid dat terugkaatst en je opnieuw hoort"},{"t":"Echopeiling","d":"het meten van een afstand met teruggekaatst geluid"},{"t":"Geluidsbron","d":"het voorwerp dat het geluid maakt"},{"t":"Decibel","d":"de eenheid van geluidssterkte"}],"sam":"<div class=\"sam-intro\"><strong>Geluid</strong> bestaat uit <strong>trillingen</strong> die zich door een stof voortplanten. De <strong>frequentie</strong> bepaalt de <strong>toonhoogte</strong>, de <strong>amplitude</strong> de <strong>geluidssterkte</strong>.</div><div class=\"sam-head\">1. Trillingen en geluid</div><p>Een <strong>geluidsbron</strong> maakt <strong>trillingen</strong>: heen-en-weergaande bewegingen. Die trillingen planten zich als <strong>geluid</strong> voort door een stof, bijvoorbeeld lucht. In het luchtledige is er geen geluid, want er is niets om te trillen.</p><div class=\"sam-head\">2. Frequentie en amplitude</div><p>De <strong>frequentie</strong> is het aantal trillingen per seconde (in hertz); de <strong>trillingstijd</strong> is de duur van één trilling. Een hoge frequentie geeft een hoge <strong>toonhoogte</strong>. De <strong>amplitude</strong> is de grootte van de uitwijking en bepaalt de <strong>geluidssterkte</strong>: hoe harder het klinkt.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Frequentie</div><div class=\"sam-formula-eq\">f = 1 / T</div><div class=\"sam-formula-note\">f de frequentie (Hz), T de trillingstijd (s).</div></div><div class=\"sam-worked\"><div class=\"sam-worked-h\">✍️ Voorbeeldopgave</div><div class=\"sam-worked-q\">Eén trilling duurt 0,01 s. Bereken de frequentie.</div><ol class=\"sam-worked-steps\"><li>Gebruik f = 1 / T.</li><li>f = 1 / 0,01.</li></ol><div class=\"sam-worked-ans\">✅ De frequentie is 100 Hz.</div></div><div class=\"sam-head\">3. Echo en geluidssnelheid</div><p>Geluid heeft een <strong>geluidssnelheid</strong> (in lucht ongeveer 340 m/s). Kaatst geluid terug, dan hoor je een <strong>echo</strong>. Met <strong>echopeiling</strong> meet je een afstand door de tijd van de echo te gebruiken.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geluid</div><div class=\"sam-definitie-body\">trillingen die zich door een stof voortplanten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Trilling</div><div class=\"sam-definitie-body\">een heen-en-weergaande beweging.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Frequentie</div><div class=\"sam-definitie-body\">het aantal trillingen per seconde, in hertz.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Trillingstijd</div><div class=\"sam-definitie-body\">de tijd van één volledige trilling.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Amplitude</div><div class=\"sam-definitie-body\">de grootte van de uitwijking van een trilling.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Toonhoogte</div><div class=\"sam-definitie-body\">hoe hoog of laag een toon klinkt; hangt af van de frequentie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geluidssterkte</div><div class=\"sam-definitie-body\">hoe hard een geluid klinkt; hangt af van de amplitude.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geluidssnelheid</div><div class=\"sam-definitie-body\">de snelheid waarmee geluid zich voortplant.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Echo</div><div class=\"sam-definitie-body\">geluid dat terugkaatst en je opnieuw hoort.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Echopeiling</div><div class=\"sam-definitie-body\">het meten van een afstand met teruggekaatst geluid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geluidsbron</div><div class=\"sam-definitie-body\">het voorwerp dat het geluid maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Decibel</div><div class=\"sam-definitie-body\">de eenheid van geluidssterkte.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Geluid»</b> is voortplantende trillingen, terwijl <b>«Trilling»</b> heen en weer bewegen is. <b>«Trilling»</b> is heen en weer bewegen, terwijl <b>«Frequentie»</b> trillingen per seconde is. <b>«Frequentie»</b> is trillingen per seconde, terwijl <b>«Trillingstijd»</b> tijd van één trilling is. <b>«Amplitude»</b> is grootte van de uitwijking, terwijl <b>«Frequentie»</b> trillingen per seconde is.</div>"},"F":{"sv":[{"v":"Wat is een kracht?","o":["Een duw of trek","Een soort energie","Een snelheid","Een temperatuur"],"c":0,"d":1,"u":"Een duw of trek op een voorwerp.","uo":["Klopt: een duw of trek op een voorwerp.","Nee, het juiste antwoord is «Een duw of trek».","Snelheid is iets anders.","Nee, het juiste antwoord is «Een duw of trek»."],"uh":"Een duw of trek op een voorwerp."},{"v":"In welke eenheid meet je kracht?","o":["In meter","In newton","In seconde","In watt"],"c":1,"d":1,"u":"Kracht in newton.","uo":["Meter is afstand.","Klopt: kracht in newton.","Seconde is tijd.","Watt is vermogen."],"uh":"In newton: Kracht in newton."},{"v":"Wat is de zwaartekracht?","o":["De snelheid","De wrijving","De aantrekking van de aarde","De temperatuur"],"c":2,"d":1,"u":"De aarde trekt aan massa.","uo":["Nee, het juiste antwoord is «De aantrekking van de aarde».","Wrijving is iets anders.","Klopt: de aarde trekt aan massa.","Nee, het juiste antwoord is «De aantrekking van de aarde»."],"uh":"De aantrekking van de aarde: De aarde trekt aan massa."},{"v":"Twee even grote krachten heffen elkaar op. Wat is er dan?","o":["Versnelling","Wrijving","Beweging","Evenwicht"],"c":3,"d":2,"u":"De krachten zijn in evenwicht.","uo":["Nee, het juiste antwoord is «Evenwicht».","Nee, het juiste antwoord is «Evenwicht».","Niet per se.","Klopt: de krachten zijn in evenwicht."],"uh":"Evenwicht: De krachten zijn in evenwicht."},{"v":"Wat doet een hefboom?","o":["Met weinig kracht veel tillen","Kracht altijd verkleinen","Warmte maken","Licht buigen"],"c":0,"d":2,"u":"Met weinig kracht een zware last tillen.","uo":["Klopt: met weinig kracht een zware last tillen.","Niet altijd verkleinen.","Nee, het juiste antwoord is «Met weinig kracht veel tillen».","Nee, het juiste antwoord is «Met weinig kracht veel tillen»."],"uh":"Met weinig kracht een zware last tillen."},{"v":"Waar draait een hefboom omheen?","o":["Om de last","Om het draaipunt","Om de kracht","Om de arm"],"c":1,"d":2,"u":"Om het draaipunt.","uo":["Nee, het juiste antwoord is «Om het draaipunt».","Klopt: om het draaipunt.","Nee, het juiste antwoord is «Om het draaipunt».","De arm is de afstand."],"uh":"Om het draaipunt."},{"v":"Wat is de stopafstand?","o":["Alleen de reactietijd","Alleen de remweg","Reactieafstand plus remweg","De snelheid"],"c":2,"d":2,"u":"Reactieafstand plus remweg.","uo":["Dat is een tijd.","Dat is maar een deel.","Klopt: reactieafstand plus remweg.","Nee, het juiste antwoord is «Reactieafstand plus remweg»."],"uh":"Reactieafstand plus remweg."},{"v":"Wat gebeurt met de remweg bij een hogere snelheid?","o":["Die wordt korter","Die blijft gelijk","Die verdwijnt","Die wordt langer"],"c":3,"d":3,"u":"Bij hogere snelheid wordt de remweg langer.","uo":["Nee, het juiste antwoord is «Die wordt langer».","Nee, het juiste antwoord is «Die wordt langer».","Nee, het juiste antwoord is «Die wordt langer».","Klopt: bij hogere snelheid wordt de remweg langer."],"uh":"Die wordt langer: Bij hogere snelheid wordt de remweg langer."},{"v":"Wat is de reactietijd?","o":["De tijd tussen zien en reageren","De tijd van het remmen","De totale ritduur","De snelheid"],"c":0,"d":2,"u":"De tijd tussen zien en reageren.","uo":["Klopt: de tijd tussen zien en reageren.","Dat is de remtijd.","Nee, het juiste antwoord is «De tijd tussen zien en reageren».","Nee, het juiste antwoord is «De tijd tussen zien en reageren»."],"uh":"De tijd tussen zien en reageren."},{"v":"Wat is de resultante?","o":["Eén losse kracht","De som van alle krachten","De wrijving","Het gewicht"],"c":1,"d":2,"u":"De som van alle krachten samen.","uo":["Nee, het juiste antwoord is «De som van alle krachten».","Klopt: de som van alle krachten samen.","Wrijving is één kracht.","Nee, het juiste antwoord is «De som van alle krachten»."],"uh":"De som van alle krachten samen."},{"v":"Wat doet de wrijvingskracht?","o":["Warmte tegenhouden","Beweging versnellen","Beweging tegenwerken","Licht buigen"],"c":2,"d":2,"u":"Wrijving werkt beweging tegen.","uo":["Nee, het juiste antwoord is «Beweging tegenwerken».","Juist niet, het juiste antwoord is «Beweging tegenwerken».","Klopt: wrijving werkt beweging tegen.","Nee, het juiste antwoord is «Beweging tegenwerken»."],"uh":"Beweging tegenwerken: Wrijving werkt beweging tegen."},{"v":"Waarom is meer afstand houden veiliger bij hoge snelheid?","o":["De reactietijd verdwijnt","De remweg wordt korter","Er is geen risico","De stopafstand is groter"],"c":3,"d":3,"u":"Bij hoge snelheid is de stopafstand groter.","uo":["Nee, het juiste antwoord is «De stopafstand is groter».","Juist langer.","Er is wel risico.","Klopt: bij hoge snelheid is de stopafstand groter."],"uh":"De stopafstand is groter: Bij hoge snelheid is de stopafstand groter."}],"begrippen":[{"t":"Kracht","d":"een duw of trek die een voorwerp kan vervormen of versnellen"},{"t":"Zwaartekracht","d":"de kracht waarmee de aarde aan massa trekt"},{"t":"Newton","d":"de eenheid van kracht"},{"t":"Resultante","d":"de som van alle krachten op een voorwerp"},{"t":"Evenwicht","d":"de toestand waarin de krachten elkaar opheffen"},{"t":"Hefboom","d":"een staaf die om een draaipunt draait om kracht te vergroten"},{"t":"Draaipunt","d":"het vaste punt waar een hefboom omheen draait"},{"t":"Moment","d":"het draai-effect van een kracht: kracht maal arm"},{"t":"Remweg","d":"de afstand die je aflegt tijdens het remmen"},{"t":"Reactietijd","d":"de tijd tussen iets zien en erop reageren"},{"t":"Stopafstand","d":"de reactieafstand plus de remweg"},{"t":"Wrijvingskracht","d":"een kracht die beweging tegenwerkt"}],"sam":"<div class=\"sam-intro\">Een <strong>kracht</strong> is een duw of trek, gemeten in <strong>newton</strong>. Een <strong>hefboom</strong> vergroot kracht rond een <strong>draaipunt</strong>. Je <strong>stopafstand</strong> is de reactieafstand plus de <strong>remweg</strong>.</div><div class=\"sam-head\">1. Krachten</div><p>Een <strong>kracht</strong> is een duw of trek die een voorwerp kan vervormen of versnellen; de eenheid is de <strong>newton</strong>. De <strong>zwaartekracht</strong> trekt alles naar de aarde. Werken meerdere krachten, dan tel je ze samen tot de <strong>resultante</strong>. Heffen ze elkaar op, dan is er <strong>evenwicht</strong>. De <strong>wrijvingskracht</strong> werkt beweging tegen.</p><div class=\"sam-head\">2. Hefbomen</div><p>Een <strong>hefboom</strong> draait om een <strong>draaipunt</strong> en maakt het mogelijk met weinig kracht een zware last te tillen. Het draai-effect heet het <strong>moment</strong>: kracht maal arm.</p><div class=\"sam-formula-box\"><div class=\"sam-formula-label\">Moment</div><div class=\"sam-formula-eq\">M = F × r</div><div class=\"sam-formula-note\">M het moment, F de kracht (N), r de arm (afstand tot het draaipunt).</div></div><div class=\"sam-head\">3. Snelheid en veiligheid</div><p>Voordat je remt, verstrijkt eerst je <strong>reactietijd</strong>: de tijd tussen zien en reageren. De afstand tijdens het remmen is de <strong>remweg</strong>. Samen vormen de reactieafstand en de remweg de <strong>stopafstand</strong>. Bij een hogere snelheid worden beide groter.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Kracht</div><div class=\"sam-definitie-body\">een duw of trek die een voorwerp kan vervormen of versnellen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zwaartekracht</div><div class=\"sam-definitie-body\">de kracht waarmee de aarde aan massa trekt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Newton</div><div class=\"sam-definitie-body\">de eenheid van kracht.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Resultante</div><div class=\"sam-definitie-body\">de som van alle krachten op een voorwerp.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Evenwicht</div><div class=\"sam-definitie-body\">de toestand waarin de krachten elkaar opheffen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Hefboom</div><div class=\"sam-definitie-body\">een staaf die om een draaipunt draait om kracht te vergroten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Draaipunt</div><div class=\"sam-definitie-body\">het vaste punt waar een hefboom omheen draait.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Moment</div><div class=\"sam-definitie-body\">het draai-effect van een kracht: kracht maal arm.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Remweg</div><div class=\"sam-definitie-body\">de afstand die je aflegt tijdens het remmen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reactietijd</div><div class=\"sam-definitie-body\">de tijd tussen iets zien en erop reageren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stopafstand</div><div class=\"sam-definitie-body\">de reactieafstand plus de remweg.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wrijvingskracht</div><div class=\"sam-definitie-body\">een kracht die beweging tegenwerkt.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Kracht»</b> is duw of trek, terwijl <b>«Moment»</b> draai-effect van kracht is. <b>«Zwaartekracht»</b> is aantrekking van de aarde, terwijl <b>«Kracht»</b> duw of trek is. <b>«Newton»</b> is eenheid van kracht, terwijl <b>«Moment»</b> draai-effect van kracht is. <b>«Resultante»</b> is som van de krachten, terwijl <b>«Evenwicht»</b> krachten heffen elkaar op is.</div>"},"G":{"sv":[{"v":"Wat is het kleinste deeltje van een stof?","o":["Een atoom","Een molecuul","Een cel","Een ion"],"c":0,"d":1,"u":"Het juiste antwoord is: Een atoom.","uo":["Klopt: het atoom.","Een molecuul bestaat uit atomen.","Een cel hoort bij biologie.","Een ion is een geladen atoom."],"uh":"Een atoom: Het juiste antwoord is: Een atoom."},{"v":"Wat is een molecuul?","o":["Eén los atoom","Atomen die aan elkaar zitten","Een geladen deeltje","Een mengsel"],"c":1,"d":2,"u":"Een groepje atomen aan elkaar.","uo":["Nee, meer atomen.","Klopt: een groepje atomen aan elkaar.","Dat is een ion.","Iets anders."],"uh":"Atomen die aan elkaar zitten: Een groepje atomen aan elkaar."},{"v":"Wat is een element?","o":["Een mengsel","Meerdere soorten atomen","Eén soort atomen","Een ion"],"c":2,"d":2,"u":"Bestaat uit één soort atomen.","uo":["Nee, het juiste antwoord is «Eén soort atomen».","Dat is een verbinding.","Klopt: bestaat uit één soort atomen.","Nee, het juiste antwoord is «Eén soort atomen»."],"uh":"Eén soort atomen: Bestaat uit één soort atomen."},{"v":"Water bestaat uit waterstof en zuurstof. Water is een...","o":["element","ion","mengsel","verbinding"],"c":3,"d":3,"u":"Meerdere soorten atomen verbonden.","uo":["Element is één soort atoom.","Nee, het juiste antwoord is «verbinding».","Een verbinding is geen mengsel.","Klopt: meerdere soorten atomen verbonden."],"uh":"verbinding: Meerdere soorten atomen verbonden."},{"v":"Wat is een zuivere stof?","o":["Eén soort deeltjes","Deeltjes door elkaar","Een geladen atoom","Een oplossing"],"c":0,"d":2,"u":"Één soort deeltjes.","uo":["Klopt: één soort deeltjes.","Dat is een mengsel.","Nee, het juiste antwoord is «Eén soort deeltjes».","Een oplossing is een mengsel."],"uh":"Eén soort deeltjes: Één soort deeltjes."},{"v":"Wat is een mengsel?","o":["Eén soort deeltjes","Meerdere stoffen door elkaar","Een enkel atoom","Een element"],"c":1,"d":2,"u":"Meerdere soorten deeltjes door elkaar.","uo":["Dat is een zuivere stof.","Klopt: meerdere soorten deeltjes door elkaar.","Nee, het juiste antwoord is «Meerdere stoffen door elkaar».","Nee, het juiste antwoord is «Meerdere stoffen door elkaar»."],"uh":"Meerdere soorten deeltjes door elkaar."},{"v":"Welk deeltje is positief geladen?","o":["Het neutron","Het elektron","Het proton","Het molecuul"],"c":2,"d":1,"u":"Het proton is positief.","uo":["Het neutron is ongeladen.","Het elektron is negatief.","Klopt: het proton is positief.","Nee, het juiste antwoord is «Het proton»."],"uh":"Het proton is positief."},{"v":"Welk deeltje is negatief geladen?","o":["Het proton","Het neutron","Het atoom","Het elektron"],"c":3,"d":2,"u":"Het elektron is negatief.","uo":["Positief, het juiste antwoord is «Het elektron».","Ongeladen, het juiste antwoord is «Het elektron».","Meestal neutraal.","Klopt: het elektron is negatief."],"uh":"Het elektron is negatief."},{"v":"Waar zitten de protonen en neutronen?","o":["In de atoomkern","In de elektronen","Buiten het atoom","Apart in een molecuul"],"c":0,"d":2,"u":"In de atoomkern.","uo":["Klopt: in de atoomkern.","Nee, het juiste antwoord is «In de atoomkern».","Nee, het juiste antwoord is «In de atoomkern».","Nee, het juiste antwoord is «In de atoomkern»."],"uh":"In de atoomkern."},{"v":"Wat is een ion?","o":["Een neutraal atoom","Een atoom met een lading","Een molecuul","Een mengsel"],"c":1,"d":2,"u":"Een atoom met een elektrische lading.","uo":["Een ion is juist geladen.","Klopt: een atoom met een elektrische lading.","Nee, het juiste antwoord is «Een atoom met een lading».","Nee, het juiste antwoord is «Een atoom met een lading»."],"uh":"Een atoom met een elektrische lading."},{"v":"Hoe haal je zout uit zout water?","o":["Door schudden","Door bevriezen","Door indampen","Door te wachten"],"c":2,"d":3,"u":"Het water verdampt, het zout blijft achter.","uo":["Nee, het juiste antwoord is «Door indampen».","Werkt niet goed.","Klopt: het water verdampt, het zout blijft achter.","Nee, het juiste antwoord is «Door indampen»."],"uh":"Door indampen: Het water verdampt, het zout blijft achter."},{"v":"Zuurstofgas bestaat uit één soort atomen. Het is een...","o":["verbinding","mengsel","ion","element"],"c":3,"d":3,"u":"Één soort atomen, dus een element.","uo":["Verbinding heeft meerdere soorten.","Nee, het juiste antwoord is «element».","Nee, het juiste antwoord is «element».","Klopt: één soort atomen, dus een element."],"uh":"element: Één soort atomen, dus een element."}],"begrippen":[{"t":"Atoom","d":"het kleinste deeltje van een element"},{"t":"Molecuul","d":"een groepje atomen dat aan elkaar zit"},{"t":"Element","d":"een stof die uit één soort atomen bestaat"},{"t":"Verbinding","d":"een stof die uit meerdere soorten atomen bestaat"},{"t":"Zuivere stof","d":"een stof die uit één soort deeltjes bestaat"},{"t":"Mengsel","d":"een stof die uit meerdere soorten deeltjes door elkaar bestaat"},{"t":"Atoomkern","d":"het midden van een atoom met protonen en neutronen"},{"t":"Elektron","d":"een negatief geladen deeltje om de kern"},{"t":"Proton","d":"een positief geladen deeltje in de kern"},{"t":"Neutron","d":"een ongeladen deeltje in de kern"},{"t":"Ion","d":"een atoom met een elektrische lading"},{"t":"Scheiden","d":"een mengsel uit elkaar halen in zuivere stoffen"}],"sam":"<div class=\"sam-intro\">Alle stoffen bestaan uit <strong>atomen</strong>. Zitten atomen aan elkaar, dan vormen ze een <strong>molecuul</strong>. Een <strong>zuivere stof</strong> heeft één soort deeltjes; een <strong>mengsel</strong> meerdere.</div><div class=\"sam-head\">1. Atomen en moleculen</div><p>Het kleinste deeltje van een stof is het <strong>atoom</strong>. Zitten atomen aan elkaar vast, dan vormen ze een <strong>molecuul</strong>. Een <strong>element</strong> bestaat uit één soort atomen (bijvoorbeeld zuurstof); een <strong>verbinding</strong> uit meerdere soorten (bijvoorbeeld water).</p><div class=\"sam-head\">2. Zuivere stof en mengsel</div><p>Een <strong>zuivere stof</strong> bestaat uit één soort deeltjes. Een <strong>mengsel</strong> bevat meerdere soorten deeltjes door elkaar. Door <strong>scheiden</strong> (zoals filtreren of indampen) haal je een mengsel weer uit elkaar.</p><div class=\"sam-head\">3. In het atoom</div><p>Een atoom heeft een <strong>atoomkern</strong> met <strong>protonen</strong> (positief) en <strong>neutronen</strong> (ongeladen). Daaromheen bewegen <strong>elektronen</strong> (negatief). Krijgt een atoom lading, bijvoorbeeld door elektronen op te nemen of af te staan, dan is het een <strong>ion</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Atoom</div><div class=\"sam-definitie-body\">het kleinste deeltje van een element.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Molecuul</div><div class=\"sam-definitie-body\">een groepje atomen dat aan elkaar zit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Element</div><div class=\"sam-definitie-body\">een stof die uit één soort atomen bestaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verbinding</div><div class=\"sam-definitie-body\">een stof die uit meerdere soorten atomen bestaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Zuivere stof</div><div class=\"sam-definitie-body\">een stof die uit één soort deeltjes bestaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Mengsel</div><div class=\"sam-definitie-body\">een stof die uit meerdere soorten deeltjes door elkaar bestaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Atoomkern</div><div class=\"sam-definitie-body\">het midden van een atoom met protonen en neutronen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Elektron</div><div class=\"sam-definitie-body\">een negatief geladen deeltje om de kern.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Proton</div><div class=\"sam-definitie-body\">een positief geladen deeltje in de kern.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Neutron</div><div class=\"sam-definitie-body\">een ongeladen deeltje in de kern.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ion</div><div class=\"sam-definitie-body\">een atoom met een elektrische lading.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Scheiden</div><div class=\"sam-definitie-body\">een mengsel uit elkaar halen in zuivere stoffen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Atoom»</b> is kleinste deeltje, terwijl <b>«Molecuul»</b> groepje atomen is. <b>«Element»</b> is één soort atomen, terwijl <b>«Verbinding»</b> meerdere soorten atomen is. <b>«Zuivere stof»</b> is één soort deeltjes, terwijl <b>«Mengsel»</b> deeltjes door elkaar is. <b>«Atoomkern»</b> is midden van het atoom, terwijl <b>«Elektron»</b> negatief deeltje is.</div>"},"H":{"sv":[{"v":"Wat is radioactiviteit?","o":["Straling uit onstabiele kernen","Licht dat straalt","Warmte uit de zon","Geluid"],"c":0,"d":2,"u":"Onstabiele kernen zenden straling uit.","uo":["Klopt: onstabiele kernen zenden straling uit.","Nee, het juiste antwoord is «Straling uit onstabiele kernen».","Nee, het juiste antwoord is «Straling uit onstabiele kernen».","Nee, het juiste antwoord is «Straling uit onstabiele kernen»."],"uh":"Straling uit onstabiele kernen: Onstabiele kernen zenden straling uit."},{"v":"Welke straling is het meest doordringend?","o":["Alfastraling","Gammastraling","Betastraling","Geen enkele"],"c":1,"d":2,"u":"Gammastraling is zeer doordringend.","uo":["Alfa is het minst doordringend.","Klopt: gammastraling is zeer doordringend.","Beta zit ertussen.","Nee, het juiste antwoord is «Gammastraling»."],"uh":"Gammastraling is zeer doordringend."},{"v":"Wat is alfastraling?","o":["Straling zonder lading","Snelle elektronen","Zware, geladen deeltjes","Gewoon licht"],"c":2,"d":2,"u":"Zware, positief geladen deeltjes.","uo":["Dat is gamma.","Dat is beta.","Klopt: zware, positief geladen deeltjes.","Nee, het juiste antwoord is «Zware, geladen deeltjes»."],"uh":"Zware, geladen deeltjes: Zware, positief geladen deeltjes."},{"v":"Wat is de halveringstijd?","o":["De totale straling","De dosis","De afstand","De tijd waarin de helft vervalt"],"c":3,"d":3,"u":"De tijd waarin de helft van de kernen vervalt.","uo":["Nee, het juiste antwoord is «De tijd waarin de helft vervalt».","Dosis is iets anders.","Nee, het juiste antwoord is «De tijd waarin de helft vervalt».","Klopt: de tijd waarin de helft van de kernen vervalt."],"uh":"De tijd waarin de helft van de kernen vervalt."},{"v":"Hoe bescherm je je tegen straling?","o":["Afscherming en afstand","Dichterbij gaan staan","Langer blootstellen","Niets doen"],"c":0,"d":2,"u":"Afscherming, afstand en korte tijd.","uo":["Klopt: afscherming, afstand en korte tijd.","Juist verder weg.","Juist korter.","Bescherming helpt wel."],"uh":"Afscherming, afstand en korte tijd."},{"v":"Radioactief materiaal zit op je huid. Dat heet...","o":["bestraling","besmetting","een dosis","halvering"],"c":1,"d":3,"u":"Materiaal op of in je lichaam is besmetting.","uo":["Bestraling komt van buitenaf.","Klopt: materiaal op of in je lichaam is besmetting.","Een dosis is een hoeveelheid.","Nee, het juiste antwoord is «besmetting»."],"uh":"besmetting: Materiaal op of in je lichaam is besmetting."},{"v":"Straling van buitenaf op je lichaam heet...","o":["halvering","besmetting","bestraling","geleiding"],"c":2,"d":2,"u":"Bestraling komt van buitenaf.","uo":["Nee, het juiste antwoord is «bestraling».","Besmetting is op of in je lichaam.","Klopt: bestraling komt van buitenaf.","Nee, het juiste antwoord is «bestraling»."],"uh":"Bestraling komt van buitenaf."},{"v":"Waarmee meet je straling?","o":["Met een thermometer","Met een lens","Met een weegschaal","Met een geigerteller"],"c":3,"d":1,"u":"Een geigerteller meet straling.","uo":["Die meet temperatuur.","Die is voor licht.","Die meet massa.","Klopt: een geigerteller meet straling."],"uh":"Met een geigerteller: Een geigerteller meet straling."},{"v":"Wat is betastraling?","o":["Snelle elektronen","Zware geladen deeltjes","Straling zonder lading","Warmte"],"c":0,"d":2,"u":"Snelle elektronen.","uo":["Klopt: snelle elektronen.","Dat is alfa.","Dat is gamma.","Nee, het juiste antwoord is «Snelle elektronen»."],"uh":"Snelle elektronen."},{"v":"Waarom is ioniserende straling gevaarlijk?","o":["Ze maakt licht","Ze kan cellen beschadigen","Ze warmt op","Ze geeft geluid"],"c":1,"d":3,"u":"Ze kan deeltjes geladen maken en cellen beschadigen.","uo":["Nee, het juiste antwoord is «Ze kan cellen beschadigen».","Klopt: ze kan deeltjes geladen maken en cellen beschadigen.","Niet vooral.","Nee, het juiste antwoord is «Ze kan cellen beschadigen»."],"uh":"Ze kan cellen beschadigen: Ze kan deeltjes geladen maken en cellen beschadigen."},{"v":"Wat is de dosis?","o":["De afstand","De halveringstijd","De hoeveelheid ontvangen straling","De soort straling"],"c":2,"d":2,"u":"De hoeveelheid ontvangen straling.","uo":["Nee, het juiste antwoord is «De hoeveelheid ontvangen straling».","Iets anders.","Klopt: de hoeveelheid ontvangen straling.","Nee, het juiste antwoord is «De hoeveelheid ontvangen straling»."],"uh":"De hoeveelheid ontvangen straling."},{"v":"Wat houdt gammastraling het beste tegen?","o":["Een vel papier","Je hand","Lucht","Een dikke laag lood"],"c":3,"d":3,"u":"Gamma is doordringend, dik lood helpt.","uo":["Papier houdt alfa tegen.","Nee, het juiste antwoord is «Een dikke laag lood».","Nee, het juiste antwoord is «Een dikke laag lood».","Klopt: gamma is doordringend, dik lood helpt."],"uh":"Een dikke laag lood: Gamma is doordringend, dik lood helpt."}],"begrippen":[{"t":"Straling","d":"energie die zich door de ruimte verplaatst als golven of deeltjes"},{"t":"Radioactiviteit","d":"het uitzenden van straling door onstabiele kernen"},{"t":"Alfastraling","d":"straling van zware, positief geladen deeltjes"},{"t":"Betastraling","d":"straling van snelle elektronen"},{"t":"Gammastraling","d":"zeer doordringende straling zonder lading"},{"t":"Ioniserende straling","d":"straling die deeltjes geladen kan maken"},{"t":"Halveringstijd","d":"de tijd waarin de helft van de kernen vervalt"},{"t":"Besmetting","d":"radioactief materiaal op of in het lichaam"},{"t":"Bestraling","d":"blootstelling aan straling van buitenaf"},{"t":"Afscherming","d":"het tegenhouden van straling met een laag materiaal"},{"t":"Dosis","d":"de hoeveelheid ontvangen straling"},{"t":"Geigerteller","d":"een apparaat dat straling meet"}],"sam":"<div class=\"sam-intro\"><strong>Radioactiviteit</strong> is het uitzenden van <strong>straling</strong> door onstabiele kernen. Er zijn drie soorten: <strong>alfa</strong>, <strong>bèta</strong> en <strong>gamma</strong>. Met <strong>afscherming</strong> en afstand bescherm je jezelf.</div><div class=\"sam-head\">1. Soorten straling</div><p><strong>Radioactiviteit</strong> ontstaat als onstabiele atoomkernen <strong>straling</strong> uitzenden. Er zijn drie soorten: <strong>alfastraling</strong> (zware, geladen deeltjes, weinig doordringend), <strong>betastraling</strong> (snelle elektronen) en <strong>gammastraling</strong> (zeer doordringend, zonder lading). Omdat deze straling deeltjes geladen kan maken, heet ze <strong>ioniserende straling</strong>.</p><div class=\"sam-head\">2. Halveringstijd en bescherming</div><p>De <strong>halveringstijd</strong> is de tijd waarin de helft van de radioactieve kernen vervalt: daarna is de straling gehalveerd. Straling van buitenaf heet <strong>bestraling</strong>; zit het radioactieve materiaal op of in je lichaam, dan is er <strong>besmetting</strong>. Je beschermt je met <strong>afscherming</strong>, afstand en korte blootstelling. De ontvangen hoeveelheid heet de <strong>dosis</strong>, die je meet met een <strong>geigerteller</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Straling</div><div class=\"sam-definitie-body\">energie die zich door de ruimte verplaatst als golven of deeltjes.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Radioactiviteit</div><div class=\"sam-definitie-body\">het uitzenden van straling door onstabiele kernen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Alfastraling</div><div class=\"sam-definitie-body\">straling van zware, positief geladen deeltjes.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Betastraling</div><div class=\"sam-definitie-body\">straling van snelle elektronen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Gammastraling</div><div class=\"sam-definitie-body\">zeer doordringende straling zonder lading.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Ioniserende straling</div><div class=\"sam-definitie-body\">straling die deeltjes geladen kan maken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Halveringstijd</div><div class=\"sam-definitie-body\">de tijd waarin de helft van de kernen vervalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Besmetting</div><div class=\"sam-definitie-body\">radioactief materiaal op of in het lichaam.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bestraling</div><div class=\"sam-definitie-body\">blootstelling aan straling van buitenaf.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Afscherming</div><div class=\"sam-definitie-body\">het tegenhouden van straling met een laag materiaal.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Dosis</div><div class=\"sam-definitie-body\">de hoeveelheid ontvangen straling.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Geigerteller</div><div class=\"sam-definitie-body\">een apparaat dat straling meet.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Straling»</b> is energie door de ruimte, terwijl <b>«Radioactiviteit»</b> kernen zenden straling uit is. <b>«Alfastraling»</b> is zware geladen deeltjes, terwijl <b>«Betastraling»</b> snelle elektronen is. <b>«Gammastraling»</b> is doordringend, geen lading, terwijl <b>«Alfastraling»</b> zware geladen deeltjes is. <b>«Ioniserende straling»</b> is maakt deeltjes geladen, terwijl <b>«Straling»</b> energie door de ruimte is.</div>"}});